// IssuingServiceHandler is an implementation of the cards.v2.IssuingService service.
type IssuingServiceHandler interface {
	// Provider-scoped delivery credentials, hash-only at rest. Minting leaves
	// existing tokens valid; revoke only after the new URL receives deliveries.
	MintWebhookToken(context.Context, *connect.Request[v2.MintWebhookTokenRequest]) (*connect.Response[v2.MintWebhookTokenResponse], error)
	RevokeWebhookToken(context.Context, *connect.Request[v2.RevokeWebhookTokenRequest]) (*connect.Response[v2.RevokeWebhookTokenResponse], error)
	// Current personal integration credentials remain manageable until the
	// platform-key migration. Only a signed-in administrator, never a key,
	// may create, list or revoke them. Service scopes cannot be minted here.
	// Creating again replaces the same administrator's personal key.
	CreateAPIKey(context.Context, *connect.Request[v2.CreateAPIKeyRequest]) (*connect.Response[v2.CreateAPIKeyResponse], error)
	ListAPIKeys(context.Context, *connect.Request[v2.ListAPIKeysRequest]) (*connect.Response[v2.ListAPIKeysResponse], error)
	RevokeAPIKey(context.Context, *connect.Request[v2.RevokeAPIKeyRequest]) (*connect.Response[v2.RevokeAPIKeyResponse], error)
	GetSettings(context.Context, *connect.Request[v2.GetSettingsRequest]) (*connect.Response[v2.GetSettingsResponse], error)
	// UpdateSettings changes the mode, the default account, the report time
	// zone and the top-up strategy. OWN needs the plan's custom-issuers
	// feature (ERROR_REASON_NOT_IN_PLAN).
	UpdateSettings(context.Context, *connect.Request[v2.UpdateSettingsRequest]) (*connect.Response[v2.UpdateSettingsResponse], error)
	// ListAccounts is the organisation's own issuer accounts (OWN mode). In
	// PLATFORM mode it is empty: the organisation does not see the platform's.
	ListAccounts(context.Context, *connect.Request[v2.ListAccountsRequest]) (*connect.Response[v2.ListAccountsResponse], error)
	// ConnectAccount stores an issuer key (encrypted; only the service reads
	// it) and checks it with the issuer. With validate_only it checks and
	// stores nothing — the onboarding's "check the connection".
	ConnectAccount(context.Context, *connect.Request[v2.ConnectAccountRequest]) (*connect.Response[v2.ConnectAccountResponse], error)
	// DisconnectAccount stops issuing from an account. Its cards stay and keep
	// syncing until closed.
	DisconnectAccount(context.Context, *connect.Request[v2.DisconnectAccountRequest]) (*connect.Response[v2.DisconnectAccountResponse], error)
	// ListBins is what can be issued: BIN, network, currency, how fast, what
	// the issuer can do with it, and what it costs (fee terms plus the
	// platform's price) — the price is known before the press.
	ListBins(context.Context, *connect.Request[v2.ListBinsRequest]) (*connect.Response[v2.ListBinsResponse], error)
	// ListFeeTerms is the issuer's conditions as numbers. No row for a kind
	// means unknown; a row with zero means free.
	ListFeeTerms(context.Context, *connect.Request[v2.ListFeeTermsRequest]) (*connect.Response[v2.ListFeeTermsResponse], error)
	// SetFeeTerms replaces the MANUAL terms of one account and BIN ("" = the
	// whole account). Terms the provider reports (source PROVIDER) are the
	// adapter's and are not written here.
	SetFeeTerms(context.Context, *connect.Request[v2.SetFeeTermsRequest]) (*connect.Response[v2.SetFeeTermsResponse], error)
	// GetBalance is the organisation's balance with the platform (PLATFORM
	// mode only): what issues and spend are paid from.
	GetBalance(context.Context, *connect.Request[v2.GetBalanceRequest]) (*connect.Response[v2.GetBalanceResponse], error)
	// ListBalanceEntries is that balance's ledger.
	ListBalanceEntries(context.Context, *connect.Request[v2.ListBalanceEntriesRequest]) (*connect.Response[v2.ListBalanceEntriesResponse], error)
	// TopUp moves money to a person's account at the issuer, when the top-up
	// module is on in MANUAL or THRESHOLD mode and the issuer can move funds
	// (ERROR_REASON_TOPUP_DISABLED otherwise).
	TopUp(context.Context, *connect.Request[v2.TopUpRequest]) (*connect.Response[v2.TopUpResponse], error)
	// Holder data: the name and address cards are presented with, chosen per
	// card, else per BIN, else per issuer account, else the organisation's
	// default. A general merchant (AVS) concern, nothing specific to any one.
	ListHolderProfiles(context.Context, *connect.Request[v2.ListHolderProfilesRequest]) (*connect.Response[v2.ListHolderProfilesResponse], error)
	// SaveHolderProfile creates (empty id) or replaces a profile and where it
	// applies.
	SaveHolderProfile(context.Context, *connect.Request[v2.SaveHolderProfileRequest]) (*connect.Response[v2.SaveHolderProfileResponse], error)
	// ArchiveHolderProfile refuses a profile something still resolves to
	// (ERROR_REASON_PROFILE_IN_USE).
	ArchiveHolderProfile(context.Context, *connect.Request[v2.ArchiveHolderProfileRequest]) (*connect.Response[v2.ArchiveHolderProfileResponse], error)
	// People's frames: what a member may issue on their own — which issuer,
	// how many cards, how large, how much in all. Breaking one answers
	// ERROR_REASON_LIMIT_REACHED. An administrator is never held to a frame.
	// ListPersonLimits: every frame for an administrator or viewer, a
	// member's own for a member.
	ListPersonLimits(context.Context, *connect.Request[v2.ListPersonLimitsRequest]) (*connect.Response[v2.ListPersonLimitsResponse], error)
	// SavePersonLimits sets one person's frame (administrator).
	SavePersonLimits(context.Context, *connect.Request[v2.SavePersonLimitsRequest]) (*connect.Response[v2.SavePersonLimitsResponse], error)
	// DeletePersonLimits lifts it (administrator).
	DeletePersonLimits(context.Context, *connect.Request[v2.DeletePersonLimitsRequest]) (*connect.Response[v2.DeletePersonLimitsResponse], error)
}

// NewIssuingServiceHandler builds an HTTP handler from the service implementation. It returns the
// path on which to mount the handler and the handler itself.
//
// By default, handlers support the Connect, gRPC, and gRPC-Web protocols with the binary Protobuf
